<?php
declare(strict_types=1);require_once __DIR__.'/config/erp.php';$pdo=srnu_db();$id=(int)($_GET['id']??$_POST['id']??0);$cot=srnu_obtener_cotizacion($id);if(!$cot){http_response_code(404);exit('Cotización no encontrada');}$dir=srnu_upload_dir('adjuntos');
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(isset($_POST['nota'])&&epost('nota')!=='')$pdo->prepare('INSERT INTO notas_internas(cotizacion_id,nota) VALUES(?,?)')->execute([$id,epost('nota')]);
 if(isset($_POST['delnota']))$pdo->prepare('DELETE FROM notas_internas WHERE id=? AND cotizacion_id=?')->execute([(int)$_POST['row_id'],$id]);
 if(isset($_POST['subir'])&&!empty($_FILES['archivo']['name'])&&$_FILES['archivo']['error']===UPLOAD_ERR_OK&&$_FILES['archivo']['size']<=20*1024*1024){$name=srnu_safe_upload_name($_FILES['archivo']['name']);if(move_uploaded_file($_FILES['archivo']['tmp_name'],$dir.'/'.$name))$pdo->prepare('INSERT INTO adjuntos(cotizacion_id,archivo,nombre_original,tipo) VALUES(?,?,?,?)')->execute([$id,'uploads/adjuntos/'.$name,$_FILES['archivo']['name'],$_FILES['archivo']['type']??'']);}
 if(isset($_POST['deladj'])){$fid=(int)$_POST['row_id'];$s=$pdo->prepare('SELECT archivo FROM adjuntos WHERE id=? AND cotizacion_id=?');$s->execute([$fid,$id]);if($r=$s->fetch()){@unlink(__DIR__.'/'.$r['archivo']);$pdo->prepare('DELETE FROM adjuntos WHERE id=? AND cotizacion_id=?')->execute([$fid,$id]);}}
 ego('notas.php?id='.$id);
}
$s=$pdo->prepare('SELECT * FROM notas_internas WHERE cotizacion_id=? ORDER BY id DESC');$s->execute([$id]);$notas=$s->fetchAll();$s=$pdo->prepare('SELECT * FROM adjuntos WHERE cotizacion_id=? ORDER BY id DESC');$s->execute([$id]);$adj=$s->fetchAll();?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Notas internas · SRNU</title><?=srnu_ui_head()?></head><body><?php srnu_appbar('cotizaciones');?><main class="w"><div class="srnu-page-heading"><div><h1>Notas y archivos internos</h1><p><?=eh($cot['folio'])?> · nunca aparecen en el PDF del cliente.</p></div><a class="btn light" href="cotizaciones.php">← Cotizaciones</a></div><div class="grid-2"><section class="panel" style="padding:18px"><h3>Nueva nota</h3><form method="post"><input type="hidden" name="id" value="<?=$id?>"><textarea name="nota" required placeholder="Pendientes, acuerdos, observaciones internas..."></textarea><button class="btn blue" name="guardar_nota" value="1">Guardar nota</button></form><div style="margin-top:14px"><?php foreach($notas as $n):?><div class="card" style="margin-bottom:10px"><div class="muted"><?=eh($n['created_at'])?></div><p><?=nl2br(eh($n['nota']))?></p><form method="post"><input type="hidden" name="id" value="<?=$id?>"><input type="hidden" name="row_id" value="<?=$n['id']?>"><button class="btn danger" name="delnota" value="1">Eliminar</button></form></div><?php endforeach;?></div></section><section class="panel" style="padding:18px"><h3>Archivos adjuntos</h3><form method="post" enctype="multipart/form-data"><input type="hidden" name="id" value="<?=$id?>"><input type="file" name="archivo" required><button class="btn blue" name="subir" value="1">Subir archivo</button></form><table style="margin-top:14px"><tr><th>Archivo</th><th>Fecha</th><th></th></tr><?php foreach($adj as $a):?><tr><td><a href="adjunto.php?id=<?=$a['id']?>" target="_blank"><?=eh($a['nombre_original'])?></a><div class="muted"><?=eh($a['tipo'])?></div></td><td><?=eh($a['created_at'])?></td><td><form method="post"><input type="hidden" name="id" value="<?=$id?>"><input type="hidden" name="row_id" value="<?=$a['id']?>"><button class="btn danger" name="deladj" value="1">Eliminar</button></form></td></tr><?php endforeach;?></table></section></div></main></body></html>
